import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 채번 순번은 초기화하지 않고 계속 증가시킨다 (초기화 기준 저장 컬럼 없음). 번호 형식은 접두어+기간+'-'+순번.
// 가정: 일괄기안 대상은 본인이 기안한 '기안' 상태 문서만이다.
// 가정: 필수값은 제목·본문이다.
// 가정: 연속결재의 본인 차례는 아직 처리 전인 결재선 중 결재선 구분·순서가 가장 앞선 결재자다.
const DRAFT_STATUS = '기안';
const PENDING_STATUS = '결재대기';
const ACTION_TYPES = ['승인', '보류', '반려'];

interface BatchResult {
  approvalDocumentId: number;
  documentNumber: string | null;
  success: boolean;
  code: string | null;
  message: string;
}

function idsOf(value: unknown): number[] {
  if (!Array.isArray(value) || value.length === 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '문서 ID 목록을 입력해 주세요.');
  }
  const ids: number[] = [];
  for (const item of value) {
    if (!/^\d+$/.test(String(item))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 ID는 숫자여야 합니다.');
    }
    const id = Number(item);
    if (!ids.includes(id)) {
      ids.push(id);
    }
  }
  return ids;
}

@Controller('api/v1')
export class FnSfr029109X75bfd0Controller {
  @Post('/approval-documents/batch-draft')
  @HttpCode(200)
  async batchDraftApprovalDocuments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const ids = idsOf(data.approvalDocumentIds);
    const approvers: { approverId: number; lineGroup: number; sequenceNo: number }[] = [];
    if (data.approvers !== undefined && data.approvers !== null) {
      if (!Array.isArray(data.approvers)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '결재선 형식이 올바르지 않습니다.');
      }
      let index = 0;
      for (const raw of data.approvers) {
        index += 1;
        const item = (raw ?? {}) as Record<string, unknown>;
        const lineGroup = item.lineGroup === undefined || item.lineGroup === '' ? 1 : Number(item.lineGroup);
        const sequenceNo = item.sequenceNo === undefined || item.sequenceNo === '' ? index : Number(item.sequenceNo);
        if (!/^\d+$/.test(String(item.approverId))) {
          throw new ApiError(400, 'VALIDATION_FAILED', '결재자를 선택해 주세요.');
        }
        if (!Number.isInteger(lineGroup) || lineGroup < 1 || !Number.isInteger(sequenceNo) || sequenceNo < 1) {
          throw new ApiError(400, 'VALIDATION_FAILED', '결재선 구분과 순서는 1 이상의 정수여야 합니다.');
        }
        approvers.push({ approverId: Number(item.approverId), lineGroup, sequenceNo });
      }
    }
    return transaction(async (db) => {
      for (const a of approvers) {
        const emp = await db.query(
          `SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)`,
          { id: a.approverId },
        );
        if (emp.length === 0) {
          throw new ApiError(400, 'VALIDATION_FAILED', '존재하지 않는 결재자가 있습니다.');
        }
      }
      for (const id of ids) {
        const found = await db.query(
          `SELECT approval_document_id FROM approval_document WHERE approval_document_id = CAST(:id AS bigint)`,
          { id },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '일괄기안 대상 문서가 존재하지 않습니다.');
        }
      }
      const results: BatchResult[] = [];
      for (const id of ids) {
        const fail = (code: string, message: string) => {
          results.push({ approvalDocumentId: id, documentNumber: null, success: false, code, message });
        };
        const rows = await db.query(
          `SELECT drafter_id, drafter_department_id, title, body, approval_status
             FROM approval_document
            WHERE approval_document_id = CAST(:id AS bigint)`,
          { id },
        );
        const doc = rows[0];
        if (String(doc.drafter_id) !== String(user.id)) {
          fail('FORBIDDEN', '본인이 기안한 문서만 일괄기안할 수 있습니다.');
          continue;
        }
        if (String(doc.approval_status) !== DRAFT_STATUS) {
          fail('INVALID_STATE', '기안 상태의 문서만 상신할 수 있습니다.');
          continue;
        }
        const missing: string[] = [];
        if (!doc.title || String(doc.title).trim() === '') {
          missing.push('제목');
        }
        if (!doc.body || String(doc.body).trim() === '') {
          missing.push('본문');
        }
        if (missing.length > 0) {
          fail('BATCH_DRAFT_VALIDATION_FAILED', '필수값 누락: ' + missing.join(', '));
          continue;
        }
        if (approvers.length === 0) {
          const cnt = await db.query(
            `SELECT COUNT(*) AS cnt FROM approval_line WHERE approval_document_id = CAST(:id AS bigint)`,
            { id },
          );
          if (Number(cnt[0].cnt) === 0) {
            fail('BATCH_DRAFT_VALIDATION_FAILED', '필수값 누락: 결재선');
            continue;
          }
        }
        const rule = await db.query(
          `SELECT numbering_rule_id FROM numbering_rule
            WHERE target_type = 'DOCUMENT'
              AND (department_id = CAST(:dept AS bigint) OR department_id IS NULL)
            ORDER BY department_id NULLS LAST
            LIMIT 1`,
          { dept: String(doc.drafter_department_id) },
        );
        if (rule.length === 0) {
          fail('BATCH_DRAFT_VALIDATION_FAILED', '문서번호 채번 규칙이 없습니다.');
          continue;
        }
        const numbered = await db.query(
          `UPDATE numbering_rule
              SET current_sequence = COALESCE(current_sequence, 0) + 1, updated_at = now()
            WHERE numbering_rule_id = CAST(:ruleId AS bigint)
        RETURNING COALESCE(prefix, '')
                  || CASE reset_unit WHEN 'DAY' THEN to_char(now(), 'YYYYMMDD') WHEN 'MONTH' THEN to_char(now(), 'YYYYMM') ELSE to_char(now(), 'YYYY') END
                  || '-' || lpad(CAST(current_sequence AS text), digits, '0') AS document_number`,
          { ruleId: String(rule[0].numbering_rule_id) },
        );
        const documentNumber = String(numbered[0].document_number);
        if (approvers.length > 0) {
          await db.execute(
            `DELETE FROM approval_line WHERE approval_document_id = CAST(:id AS bigint)`,
            { id },
          );
          for (const a of approvers) {
            await db.execute(
              `INSERT INTO approval_line (approval_document_id, approver_id, line_group, sequence_no, created_at, updated_at)
               VALUES (CAST(:id AS bigint), CAST(:approverId AS bigint), CAST(:lineGroup AS integer), CAST(:sequenceNo AS integer), now(), now())`,
              { id, approverId: a.approverId, lineGroup: a.lineGroup, sequenceNo: a.sequenceNo },
            );
          }
        }
        await db.execute(
          `UPDATE approval_document
              SET approval_status = :status, document_number = :documentNumber, submitted_at = now(), updated_at = now()
            WHERE approval_document_id = CAST(:id AS bigint)`,
          { id, status: PENDING_STATUS, documentNumber },
        );
        await db.execute(
          `INSERT INTO notification (employee_id, notification_type, event_type, title, target_type, target_id, read_yn, occurred_at, created_at, updated_at)
           SELECT approver_id, 'ALERT', :eventType, :title, 'DOCUMENT', CAST(:id AS bigint), false, now(), now(), now()
             FROM approval_line
            WHERE approval_document_id = CAST(:id AS bigint)
            ORDER BY line_group, sequence_no
            LIMIT 1`,
          { id, eventType: PENDING_STATUS, title: ('결재 요청: ' + String(doc.title)).slice(0, 200) },
        );
        results.push({ approvalDocumentId: id, documentNumber, success: true, code: null, message: '상신했습니다.' });
      }
      return { results };
    });
  }

  @Post('/approval-documents/batch-process')
  @HttpCode(200)
  async batchProcessApprovalDocuments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const ids = idsOf(data.approvalDocumentIds);
    const actionType = String(data.actionType ?? '');
    if (!ACTION_TYPES.includes(actionType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 유형은 승인·보류·반려 중 하나여야 합니다.');
    }
    const opinionText = data.opinion === undefined || data.opinion === null ? '' : String(data.opinion).trim();
    const opinion = opinionText === '' ? null : opinionText;
    if (actionType === '반려' && opinion === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '반려할 때는 결재 의견을 입력해 주세요.');
    }
    return transaction(async (db) => {
      for (const id of ids) {
        const found = await db.query(
          `SELECT approval_document_id FROM approval_document WHERE approval_document_id = CAST(:id AS bigint)`,
          { id },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '연속결재 대상 문서가 존재하지 않습니다.');
        }
      }
      const results: BatchResult[] = [];
      for (const id of ids) {
        const rows = await db.query(
          `SELECT document_number, title, approval_status FROM approval_document WHERE approval_document_id = CAST(:id AS bigint)`,
          { id },
        );
        const doc = rows[0];
        const documentNumber = doc.document_number ? String(doc.document_number) : null;
        const status = String(doc.approval_status);
        if (status !== PENDING_STATUS && status !== '진행중') {
          results.push({ approvalDocumentId: id, documentNumber, success: false, code: 'INVALID_STATE', message: '결재대기 문서가 아니어서 건너뜁니다.' });
          continue;
        }
        const turn = await db.query(
          `SELECT approval_line_id, approver_id FROM approval_line
            WHERE approval_document_id = CAST(:id AS bigint) AND action_type IS NULL
            ORDER BY line_group, sequence_no
            LIMIT 1`,
          { id },
        );
        if (turn.length === 0 || String(turn[0].approver_id) !== String(user.id)) {
          results.push({ approvalDocumentId: id, documentNumber, success: false, code: 'NOT_APPROVER_TURN', message: '본인 결재 차례가 아니어서 건너뜁니다.' });
          continue;
        }
        await db.execute(
          `UPDATE approval_line
              SET action_type = :actionType, opinion = CAST(:opinion AS text), processed_at = now(), updated_at = now()
            WHERE approval_line_id = CAST(:lineId AS bigint)`,
          { actionType, opinion, lineId: String(turn[0].approval_line_id) },
        );
        const left = await db.query(
          `SELECT COUNT(*) AS cnt FROM approval_line WHERE approval_document_id = CAST(:id AS bigint) AND action_type IS NULL`,
          { id },
        );
        let nextStatus = actionType;
        if (actionType === '승인') {
          nextStatus = Number(left[0].cnt) > 0 ? '진행중' : '승인';
        }
        await db.execute(
          `UPDATE approval_document SET approval_status = :nextStatus, updated_at = now() WHERE approval_document_id = CAST(:id AS bigint)`,
          { id, nextStatus },
        );
        await db.execute(
          `INSERT INTO notification (employee_id, notification_type, event_type, title, target_type, target_id, read_yn, occurred_at, created_at, updated_at)
           SELECT drafter_id, 'ALERT', :eventType, :title, 'DOCUMENT', approval_document_id, false, now(), now(), now()
             FROM approval_document
            WHERE approval_document_id = CAST(:id AS bigint)`,
          { id, eventType: '결재' + actionType, title: ('결재 ' + actionType + ': ' + String(doc.title)).slice(0, 200) },
        );
        results.push({ approvalDocumentId: id, documentNumber, success: true, code: null, message: actionType + ' 처리했습니다.' });
      }
      return { results };
    });
  }
}

