import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  NumberInput,
  RefName,
  Select,
  Tiles,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

interface ApproverItem {
  approverId: number | string;
  lineGroup: number | string;
  sequenceNo: number | string;
}

export default function FnSfr029109X75bfd0Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [mode, setMode] = useState<'' | 'draft' | 'process'>('');
  const [ids, setIds] = useState<(number | string)[]>([]);
  const [pickDoc, setPickDoc] = useState<number | string>('');
  const [approvers, setApprovers] = useState<ApproverItem[]>([]);
  const [pickApprover, setPickApprover] = useState<number | string>('');
  const [lineGroup, setLineGroup] = useState<number | string>(1);
  const [actionType, setActionType] = useState('승인');
  const [opinion, setOpinion] = useState('');

  const successCount = results.filter((r) => r.success === true).length;
  const failCount = results.length - successCount;

  function open(next: 'draft' | 'process') {
    setIds([]);
    setPickDoc('');
    setApprovers([]);
    setPickApprover('');
    setLineGroup(1);
    setActionType('승인');
    setOpinion('');
    setMode(next);
  }

  function addDoc(value: number | string) {
    setPickDoc('');
    if (value === '' || ids.includes(value)) {
      return;
    }
    setIds([...ids, value]);
  }

  function addApprover(value: number | string) {
    setPickApprover('');
    if (value === '') {
      return;
    }
    setApprovers([...approvers, { approverId: value, lineGroup, sequenceNo: approvers.length + 1 }]);
  }

  async function submitDraft() {
    if (ids.length === 0) {
      throw new Error('기안할 문서를 선택해 주세요.');
    }
    const body: Row = { approvalDocumentIds: ids };
    if (approvers.length > 0) {
      body.approvers = approvers;
    }
    const res = await call<{ results: Row[] }>('POST', '/approval-documents/batch-draft', role, body);
    setResults(res.results);
    setMode('');
    notify('일괄기안을 처리했습니다.');
  }

  async function submitProcess() {
    if (ids.length === 0) {
      throw new Error('결재할 문서를 선택해 주세요.');
    }
    if (actionType === '반려' && opinion.trim() === '') {
      throw new Error('반려할 때는 결재 의견을 입력해 주세요.');
    }
    const res = await call<{ results: Row[] }>('POST', '/approval-documents/batch-process', role, {
      approvalDocumentIds: ids,
      actionType,
      opinion,
    });
    setResults(res.results);
    setMode('');
    notify('연속결재를 처리했습니다.');
  }

  const docList = (
    <Field label='문서' required wide hint='문서를 고르면 목록에 추가됩니다.'>
      <div>
        <LookupSelect table='approval_document' role={role} value={pickDoc} onChange={addDoc} placeholder='문서 추가' />
        <ul>
          {ids.map((id) => (
            <li key={String(id)}>
              <RefName table='approval_document' role={role} value={id} />
              <button type='button' onClick={() => setIds(ids.filter((x) => x !== id))}>제거</button>
            </li>
          ))}
        </ul>
      </div>
    </Field>
  );

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['처리 문서', results.length],
            ['성공', successCount],
            ['제외·건너뜀', failCount],
          ]}
        />
      </section>
      <section className='box span-12'>
        <h2>처리 결과</h2>
        <Band total={results.length}>
          <button type='button' onClick={() => open('draft')}>일괄기안</button>
          <button type='button' onClick={() => open('process')}>연속결재</button>
        </Band>
        <DataTable
          rows={results}
          empty='처리한 문서가 없습니다.'
          columns={[
            { key: 'approvalDocumentId', label: '문서', render: (r) => <RefName table='approval_document' role={role} value={r.approvalDocumentId} /> },
            { key: 'documentNumber', label: '문서번호', render: (r) => <span>{r.documentNumber ? String(r.documentNumber) : '-'}</span> },
            { key: 'success', label: '결과', render: (r) => <Badge value={r.success === true ? '완료' : '실패'} /> },
            { key: 'message', label: '사유' },
          ]}
        />
      </section>
      {mode === 'draft' && (
        <Drawer title='일괄기안' onClose={() => setMode('')}>
          <Form onSubmit={submitDraft} submit='상신'>
            {docList}
            <Field label='결재선 구분'>
              <NumberInput value={lineGroup} onChange={setLineGroup} />
            </Field>
            <Field label='결재자' wide hint='순서대로 추가합니다. 비우면 문서에 저장된 결재선을 씁니다.'>
              <div>
                <LookupSelect table='employee' role={role} value={pickApprover} onChange={addApprover} placeholder='결재자 추가' />
                <ol>
                  {approvers.map((a, i) => (
                    <li key={i}>
                      <span>{String(a.lineGroup)}구분 </span>
                      <RefName table='employee' role={role} value={a.approverId} />
                      <button type='button' onClick={() => setApprovers(approvers.filter((_, j) => j !== i))}>제거</button>
                    </li>
                  ))}
                </ol>
              </div>
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'process' && (
        <Drawer title='연속결재' onClose={() => setMode('')}>
          <Form onSubmit={submitProcess} submit='처리'>
            {docList}
            <Field label='처리 유형' required>
              <Select
                value={actionType}
                onChange={setActionType}
                options={[['승인', '승인'], ['보류', '보류'], ['반려', '반려']]}
              />
            </Field>
            <Field label='결재 의견' wide required={actionType === '반려'}>
              <TextInput value={opinion} onChange={setOpinion} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
